def decidir_promocao(metrica_atual, metrica_candidato, limiar_minimo=0.02):
    # Só promove se a melhora for de pelo menos um limiar mínimo definido.
    # O round evita que 0.82 - 0.80 vire 0.0199999... e escape do limiar
    melhora = round(metrica_candidato - metrica_atual, 6)
    if melhora >= limiar_minimo:
        return "promover"
    return "manter_atual"


def checar_rollback(metrica_pos_deploy, metrica_baseline, queda_maxima=0.03):
    # Critério definido ANTES do incidente, não decidido durante ele
    queda = round(metrica_baseline - metrica_pos_deploy, 6)
    if queda >= queda_maxima:
        return "rollback"
    return "seguir_monitorando"
